{
    "name": "update_lead",
    "description": "Update an existing CRM lead/opportunity with new data from the conversation",
    "parameters": {
        "type": "object",
        "properties": {
            "lead_id": {
                "type": "integer",
                "description": "ID of the lead to update. If omitted, the lead linked to the current chat room will be used."
            },
            "name": {
                "type": "string",
                "description": "Updated lead title (only if it needs to change)"
            },
            "contact_name": {
                "type": "string",
                "description": "Contact person name"
            },
            "email": {
                "type": "string",
                "description": "Email address provided by the customer"
            },
            "phone": {
                "type": "string",
                "description": "Phone number provided by the customer"
            },
            "description": {
                "type": "string",
                "description": "New information or updated conversation summary to append"
            },
            "intent_signal": {
                "type": "string",
                "description": "Updated reason why this lead is commercially qualified"
            },
            "lead_temperature": {
                "type": "string",
                "description": "Updated lead temperature: warm or hot"
            },
            "sentiment_summary": {
                "type": "string",
                "description": "Updated customer sentiment summary"
            },
            "preferred_contact_time": {
                "type": "string",
                "description": "Best time window to contact the customer"
            },
            "next_action": {
                "type": "string",
                "description": "Next commercial action agreed with customer"
            }
        },
        "required": []
    }
}

result = {
    'success': True,
    'lead_id': False,
    'message': '',
    'updated': False,
}

try:
    from markupsafe import Markup
    import re

    room_id = room.id if room else False
    agent_id = agent.id if agent else False

    def _clean(value):
        if value is None:
            return ''
        return str(value).strip()

    def _normalize_plain_text(value):
        text = _clean(value)
        if not text:
            return ''
        text = re.sub(r'<br\s*/?>', '\n', text, flags=re.IGNORECASE)
        text = re.sub(r'</p\s*>', '\n', text, flags=re.IGNORECASE)
        text = re.sub(r'<p[^>]*>', '', text, flags=re.IGNORECASE)
        text = re.sub(r'<[^>]+>', '', text)
        lines = [line.strip() for line in text.splitlines() if line.strip()]
        return '\n'.join(lines)

    lead_id_param = params.get('lead_id')
    name = _clean(params.get('name'))
    contact_name = _clean(params.get('contact_name'))
    email = _clean(params.get('email')).lower()
    phone = _clean(params.get('phone'))
    description = _normalize_plain_text(params.get('description'))
    intent_signal = _normalize_plain_text(params.get('intent_signal'))
    lead_temperature = _clean(params.get('lead_temperature')).lower()
    sentiment_summary = _normalize_plain_text(params.get('sentiment_summary'))
    preferred_contact_time = _normalize_plain_text(params.get('preferred_contact_time'))
    next_action = _normalize_plain_text(params.get('next_action'))

    # Resolve execution user for write access.
    # Do NOT fall back to agent.create_uid — that causes the agent configurator
    # to appear as the CRM record author in the chatter.
    if room and room.assigned_to_id and not room.assigned_to_id.share:
        execution_user = room.assigned_to_id
    else:
        execution_user = env.ref('base.user_admin')

    lead_model = env['crm.lead'].sudo().with_user(execution_user)

    # Resolve the lead: by explicit ID first, then by room link.
    target_lead = None
    if lead_id_param:
        target_lead = lead_model.browse(int(lead_id_param)).exists()

    if not target_lead and room_id and 'chatroom_room_ids' in env['crm.lead']._fields:
        target_lead = lead_model.search(
            [('chatroom_room_ids', 'in', [room_id]),
             ('type', 'in', ['lead', 'opportunity'])],
            limit=1, order='id desc'
        )

    if not target_lead:
        result['success'] = False
        result['message'] = (
            'No lead found to update. Use create_lead first to create a lead for this conversation.'
        )
        raise ValueError(result['message'])

    temperature_label_map = {
        'cold': 'fría',
        'warm': 'tibia',
        'hot': 'caliente',
    }

    def _build_note(base_description):
        parts = []
        if base_description:
            parts.append(base_description)
        if intent_signal:
            parts.append(f"Señal de intención: {intent_signal}")
        if lead_temperature in temperature_label_map:
            parts.append(f"Temperatura del lead: {temperature_label_map[lead_temperature]}")
        if sentiment_summary:
            parts.append(f"Sentimiento: {sentiment_summary}")
        if preferred_contact_time:
            parts.append(f"Horario preferido de contacto: {preferred_contact_time}")
        if next_action:
            parts.append(f"Próxima acción: {next_action}")
        return '<br/>'.join(parts).strip()

    note_text = _build_note(description)

    update_vals = {}

    if name and name != target_lead.name:
        update_vals['name'] = name
    if contact_name and not target_lead.contact_name:
        update_vals['contact_name'] = contact_name
    if email and not target_lead.email_from:
        update_vals['email_from'] = email
    if phone and not target_lead.phone:
        update_vals['phone'] = phone
    if note_text:
        previous = target_lead.description or ''
        if note_text not in previous:
            update_vals['description'] = f"{previous}\n\n[AI update]\n{note_text}".strip()

    probability_by_temp = {'warm': 40.0, 'hot': 70.0}
    priority_by_temp = {'warm': '1', 'hot': '2'}

    if lead_temperature in probability_by_temp:
        current_probability = target_lead.probability or 0.0
        target_probability = probability_by_temp[lead_temperature]
        if target_probability > current_probability:
            update_vals['probability'] = target_probability

        target_priority = priority_by_temp[lead_temperature]
        if (target_lead.priority or '0') < target_priority:
            update_vals['priority'] = target_priority

    if update_vals:
        target_lead.write(update_vals)

    # Ensure room link exists.
    if room_id and 'chatroom_room_ids' in env['crm.lead']._fields:
        target_lead.write({'chatroom_room_ids': [(4, room_id)]})

    result['lead_id'] = target_lead.id
    result['updated'] = True
    result['message'] = f'Lead updated successfully (ID: {target_lead.id})'

    # Post chatter note.
    if agent_id:
        agent_rec = env['chatroom.ai.agent'].browse(agent_id)
        chat_url = f"/web#action=chatroom.action_chatroom_app&room_id={room_id}"
        message_body = (
            f'<p>Lead updated by AI agent <strong>{agent_rec.name}</strong> '
            f'from the chat conversation.</p>'
            f'<p><a href="{chat_url}" target="_blank">View source chat</a></p>'
        )
        target_lead.with_user(execution_user).message_post(
            body=Markup(message_body),
            subject='Lead updated by AI',
            message_type='comment',
            subtype_xmlid='mail.mt_note',
            author_id=(
                execution_user.partner_id.id
                if execution_user and execution_user.partner_id
                else False
            ),
        )

except Exception as e:
    if not result.get('updated'):
        result['success'] = False
        result['message'] = f'Error updating lead: {str(e)}'
